INSERT INTO broadcast_text (ID,LanguageID,Text,Text1) SELECT d.entry,0,d.content_default,d.content_default FROM db_script_string d JOIN (SELECT dataint AS id FROM event_scripts WHERE command=0 UNION SELECT dataint AS id FROM spell_scripts WHERE command=0 UNION SELECT dataint AS id FROM gameobject_scripts WHERE command=0 UNION SELECT dataint AS id FROM waypoint_scripts WHERE command=0) r ON r.id=d.entry WHERE NOT EXISTS (SELECT 1 FROM broadcast_text b WHERE b.ID=d.entry);
INSERT INTO broadcast_text_locale (ID,locale,Text,Text1) SELECT d.entry,'koKR',d.content_loc1,d.content_loc1 FROM db_script_string d JOIN (SELECT dataint AS id FROM event_scripts WHERE command=0 UNION SELECT dataint AS id FROM spell_scripts WHERE command=0 UNION SELECT dataint AS id FROM gameobject_scripts WHERE command=0 UNION SELECT dataint AS id FROM waypoint_scripts WHERE command=0) r ON r.id=d.entry WHERE COALESCE(d.content_loc1,'')<>'' AND NOT EXISTS (SELECT 1 FROM broadcast_text_locale b WHERE b.ID=d.entry AND b.locale='koKR');
